"use server";

/**
 * Registers a webhook endpoint; plan and flag gated.
 *
 * Owner D. Two independent gates: the `webhooks` feature flag (which is itself
 * plan-derived) and the numeric `webhooks` quota. Both are checked because a
 * flag can be force-enabled through an org override while the quota still
 * applies.
 *
 * Must call (do not reimplement): createWebhookSchema, can, isEnabled,
 * getPlanLimits, getActor, toActionResult
 */

import {
  FeatureUnavailableError,
  ForbiddenActionError,
  PlanLimitError,
} from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { createWebhookSchema, type CreateWebhookInput } from "@/schemas/webhook";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { createWebhook, listWebhooks } from "@/server/services/webhook-service";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { ActionResult } from "@/types/api";

const run = withAction<typeof createWebhookSchema, WebhookEndpointRow>(
  createWebhookSchema,
  async (raw, actor) => {
    const input = raw as CreateWebhookInput;

    const allowed = can(actor, "webhook:manage", {
      kind: "webhook",
      orgId: input.orgId,
      webhookId: null,
    });
    if (!allowed) {
      throw new ForbiddenActionError("webhook:manage");
    }

    const { organization } = await getOrganizationSummary(actor, input.orgId);
    if (!isEnabled("webhooks", buildFlagContext(actor, organization))) {
      throw new FeatureUnavailableError("webhooks");
    }

    const limits = getPlanLimits(organization.plan);
    const existing = await listWebhooks(actor, input.orgId);
    if (existing.length >= limits.webhooks) {
      throw new PlanLimitError("webhooks", limits.webhooks, existing.length);
    }

    const endpoint = await createWebhook(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.hours);
    return endpoint;
  },
  { revalidate: ["webhooks"], cacheProfile: "hours" },
);

export async function createWebhookAction(
  raw: unknown,
): Promise<ActionResult<WebhookEndpointRow>> {
  return run(raw);
}
/**
 * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit
 */
import { createHmac } from "node:crypto";
import { wouldExceedLimit } from "@/config/plan-limits";
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { requireFound, webhookResource } from "./_support";
import type {
  CreateWebhookInput,
  DeleteWebhookInput,
  UpdateWebhookInput,
} from "@/schemas/webhook";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";

/** Length in bytes of a generated endpoint signing secret. */
const SECRET_BYTES = 32;

export async function listWebhooks(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly WebhookEndpointRow[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "webhook:manage", webhookResource(orgId, null));
  return webhookRepo.listEndpoints(orgId);
}

/**
 * Creating an endpoint is gated twice: the `webhooks` flag has to be on for
 * the org's plan, and the plan's endpoint count must have room. A secret is
 * minted here and never regenerated — rotating it means deleting the endpoint.
 */
export async function createWebhook(
  actor: Actor,
  input: CreateWebhookInput,
): Promise<WebhookEndpointRow> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, null));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (!isEnabled("webhooks", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {
    throw new Error("Outgoing webhooks are not included in this plan");
  }

  const used = await webhookRepo.countEndpoints(input.orgId);
  if (wouldExceedLimit(org.plan, "webhooks", used)) {
    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);
  }

  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));
}

export async function updateWebhook(
  actor: Actor,
  input: UpdateWebhookInput,
): Promise<WebhookEndpointRow> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
  return webhookRepo.updateEndpoint(input);
}

export async function deleteWebhook(
  actor: Actor,
  input: DeleteWebhookInput,
): Promise<void> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
  await webhookRepo.deleteEndpoint(input.orgId, input.webhookId);
}

/**
 * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes
 * this from the same secret — it is the only thing proving the delivery came
 * from Taskflow, so the payload string must be signed byte-for-byte as sent.
 */
export function signPayload(secret: string, payload: string): string {
  return createHmac("sha256", secret).update(payload, "utf8").digest("hex");
}

/**
 * Fans domain events out into the delivery table. Each org's endpoints
 * declare which event types they want, so an endpoint only ever receives what
 * it subscribed to; the job drains the rows afterwards.
 */
export function registerWebhookListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("webhook.delivery_requested", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        payload.eventType,
        JSON.stringify(payload.payload),
      );
    }),
    subscribe("issue.created", async (payload) => {
      await enqueueForOrg(payload.orgId, "issue.created", JSON.stringify(payload));
    }),
    subscribe("issue.status_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "issue.status_changed",
        JSON.stringify(payload),
      );
    }),
    subscribe("comment.created", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "comment.created",
        JSON.stringify(payload),
      );
    }),
    subscribe("billing.plan_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "billing.plan_changed",
        JSON.stringify(payload),
      );
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

async function enqueueForOrg(
  orgId: OrgId,
  eventType: string,
  payload: string,
): Promise<void> {
  const endpoints = await webhookRepo.listEndpoints(orgId);

  for (const endpoint of endpoints) {
    if (!endpoint.enabled) continue;

    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];
    if (!wanted.includes(eventType)) continue;

    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);
  }
}

function flagContextFor(
  actor: Actor,
  plan: FlagContext["plan"],
  overrides: readonly string[],
): FlagContext {
  return {
    orgId: actor.orgId,
    userId: actor.userId,
    plan,
    role: actor.role,
    overrides,
  };
}
import type { LimitedResource, PlanId } from "@/types/billing";
import type { FeatureFlagKey } from "@/types/feature-flag";

/**
 * The one place plan quotas are declared.
 *
 * `BillingService`, the invite flow, the project-create action, the webhook
 * settings page, the usage meter component and the seat-limit job all read
 * their numbers from here via `getPlanLimits()`. Adding a field to
 * `PlanLimits` therefore ripples into every one of those call sites — that
 * ripple is intentional and is what keeps the quotas honest.
 */
export interface PlanLimits {
  readonly plan: PlanId;
  readonly seats: number;
  readonly projects: number;
  readonly issuesPerProject: number;
  readonly storageMb: number;
  readonly apiRequestsPerHour: number;
  readonly webhooks: number;
  readonly retentionDays: number;
  readonly includedFlags: readonly FeatureFlagKey[];
  readonly priceCentsPerSeatMonthly: number;
}

/** `Infinity` is the sanctioned representation of "no limit". */
export const UNLIMITED = Number.POSITIVE_INFINITY;

export const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {
  free: {
    plan: "free",
    seats: 3,
    projects: 2,
    issuesPerProject: 100,
    storageMb: 100,
    apiRequestsPerHour: 100,
    webhooks: 0,
    retentionDays: 30,
    includedFlags: ["command_palette"],
    priceCentsPerSeatMonthly: 0,
  },
  starter: {
    plan: "starter",
    seats: 10,
    projects: 10,
    issuesPerProject: 1_000,
    storageMb: 2_000,
    apiRequestsPerHour: 1_000,
    webhooks: 2,
    retentionDays: 90,
    includedFlags: ["command_palette", "kanban_board", "csv_export"],
    priceCentsPerSeatMonthly: 900,
  },
  growth: {
    plan: "growth",
    seats: 50,
    projects: 100,
    issuesPerProject: 10_000,
    storageMb: 20_000,
    apiRequestsPerHour: 10_000,
    webhooks: 10,
    retentionDays: 365,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
    ],
    priceCentsPerSeatMonthly: 1_900,
  },
  enterprise: {
    plan: "enterprise",
    seats: UNLIMITED,
    projects: UNLIMITED,
    issuesPerProject: UNLIMITED,
    storageMb: 500_000,
    apiRequestsPerHour: 100_000,
    webhooks: UNLIMITED,
    retentionDays: 2_555,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
      "advanced_search",
      "public_projects",
      "ai_issue_summary",
    ],
    priceCentsPerSeatMonthly: 3_900,
  },
};

/** Plans ordered cheapest → richest; used for "at least this plan" checks. */
export const PLAN_ORDER: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export function getPlanLimits(plan: PlanId): PlanLimits {
  return PLAN_LIMITS[plan];
}

/** Reads one numeric quota without the caller destructuring `PlanLimits`. */
export function getLimit(plan: PlanId, resource: LimitedResource): number {
  return getPlanLimits(plan)[resource];
}

/** True when `plan` is at least as rich as `minPlan`. */
export function planAtLeast(plan: PlanId, minPlan: PlanId): boolean {
  return PLAN_ORDER.indexOf(plan) >= PLAN_ORDER.indexOf(minPlan);
}

/** True when consuming `requested` more units would breach the quota. */
export function wouldExceedLimit(
  plan: PlanId,
  resource: LimitedResource,
  used: number,
  requested = 1,
): boolean {
  return used + requested > getLimit(plan, resource);
}
"use client";

/**
 * Endpoint list plus the "add endpoint" form.
 *
 * Owner D. Private to the webhooks route. The event-type checkboxes are driven
 * by `webhookEventTypeSchema` so the list of subscribable events cannot drift
 * from what the server will accept.
 */

import { useActionState } from "react";
import { fieldErrorsFromZod } from "@/lib/errors";
import { createWebhookSchema, webhookEventTypeSchema } from "@/schemas/webhook";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { ActionResult } from "@/types/api";
import type { OrgId, WebhookId } from "@/types/common";

export type WebhookManagerProps = {
  orgId: OrgId;
  endpoints: readonly WebhookEndpointRow[];
  atLimit: boolean;
  onCreate: (input: unknown) => Promise<ActionResult<WebhookEndpointRow>>;
  onDelete: (input: unknown) => Promise<ActionResult<null>>;
};

type CreateState = ActionResult<WebhookEndpointRow> | null;

const EVENT_TYPES = webhookEventTypeSchema.options;

export function WebhookManager(props: WebhookManagerProps) {
  const { orgId, endpoints, atLimit, onCreate, onDelete } = props;

  const [state, submit, pending] = useActionState<CreateState, FormData>(
    async (_previous, formData) => {
      const parsed = createWebhookSchema.safeParse({
        orgId,
        url: String(formData.get("url") ?? ""),
        eventTypes: formData.getAll("eventTypes").map(String),
      });

      if (!parsed.success) {
        return {
          ok: false,
          error: {
            code: "validation_failed",
            message: "Check the endpoint details.",
            fieldErrors: fieldErrorsFromZod(parsed.error),
          },
        };
      }

      return onCreate(parsed.data);
    },
    null,
  );

  const fieldErrors = state?.ok === false ? (state.error.fieldErrors ?? {}) : {};

  return (
    <div className="space-y-8">
      <ul className="space-y-2">
        {endpoints.map((endpoint) => (
          <li
            key={endpoint.id}
            className="flex items-start gap-4 rounded-md border border-slate-200 bg-white px-4 py-3 text-sm"
          >
            <div className="min-w-0 flex-1">
              <p className="truncate font-medium">{endpoint.url}</p>
              <p className="mt-0.5 text-xs text-slate-500">
                {endpoint.enabled ? "Enabled" : "Disabled"} · {endpoint.eventTypes}
              </p>
            </div>
            <button
              type="button"
              onClick={() => {
                void onDelete({ orgId, webhookId: endpoint.id as WebhookId });
              }}
              className="text-xs text-rose-600"
            >
              Delete
            </button>
          </li>
        ))}
      </ul>

      <form action={submit} className="space-y-4 border-t border-slate-200 pt-6">
        <h2 className="text-sm font-semibold">Add an endpoint</h2>

        {atLimit ? (
          <p className="rounded bg-amber-50 px-3 py-2 text-sm text-amber-800">
            This plan&apos;s webhook quota is full. Delete one first, or upgrade.
          </p>
        ) : null}

        {state?.ok === false && state.error.code === "plan_limit_exceeded" ? (
          <p role="alert" className="rounded bg-rose-50 px-3 py-2 text-sm text-rose-700">
            {state.error.message}
          </p>
        ) : null}

        <div className="space-y-1">
          <label htmlFor="url" className="text-sm font-medium">
            Endpoint URL
          </label>
          <input
            id="url"
            name="url"
            type="url"
            required
            disabled={atLimit}
            placeholder="https://example.com/hooks/taskflow"
            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm disabled:bg-slate-100"
          />
          {fieldErrors.url !== undefined ? (
            <p className="text-xs text-rose-600">{fieldErrors.url[0]}</p>
          ) : null}
        </div>

        <fieldset className="space-y-2">
          <legend className="text-sm font-medium">Events</legend>
          <div className="grid gap-1 sm:grid-cols-2">
            {EVENT_TYPES.map((eventType) => (
              <label key={eventType} className="flex items-center gap-2 text-sm">
                <input
                  type="checkbox"
                  name="eventTypes"
                  value={eventType}
                  disabled={atLimit}
                />
                {eventType}
              </label>
            ))}
          </div>
          {fieldErrors.eventTypes !== undefined ? (
            <p className="text-xs text-rose-600">{fieldErrors.eventTypes[0]}</p>
          ) : null}
        </fieldset>

        <button
          type="submit"
          disabled={atLimit || pending}
          className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-60"
        >
          {pending ? "Adding…" : "Add endpoint"}
        </button>
      </form>
    </div>
  );
}
